use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},io::Read,process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const ROOT:&str="/tmp/zopro-front-end-counters";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn pin(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();let h=hash(p);if let Some(old)=pins.insert(p.to_str().unwrap().into(),h.clone()){assert_eq!(old,h);}}
fn receipt(p:&Path){let e=read(p.join("exit.json"));assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{stream}.log"))),e[format!("{stream}_sha256")].as_str().unwrap());}}
fn panels()->Vec<(&'static str,Vec<String>)>{vec![
 ("slots",vec!["cycles:u".into(),"cpu/event=0x1a0,umask=0x01/u".into(),"cpu/event=0x1a0,umask=0x1e/u".into(),"cpu/event=0x1a0,umask=0x60/u".into()]),
 ("ops",vec!["cycles:u".into(),"cpu/event=0xc1/u".into(),"cpu/event=0xaa,umask=0x07/u".into(),"instructions:u".into()]),
 ("fetch",vec!["cycles:u".into(),"cpu/event=0x1a0,umask=0x01,cmask=0x08/u".into(),"cpu/event=0x82/u".into(),"cpu/event=0x83/u".into()])
]}
fn main(){let r=Path::new(ROOT);if std::env::args().nth(1).as_deref()==Some("finalize"){finalize(r);return;}
 let base=read("/tmp/zopro-grouping-module/production-source-manifest.json");let arts=read("/tmp/zopro-grouping-module/native/candidate/artifacts.json");let mut pins=BTreeMap::new();for(n,h)in base["source_files_sha256"].as_object().unwrap(){let p=Path::new("/home/ubuntu/src/zk-tools/zopro").join(n);assert_eq!(hash(&p),h.as_str().unwrap());pin(&p,&mut pins);}for(p,h)in arts["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(p,&mut pins);}let sdk=arts["binary"].as_str().unwrap();assert_eq!(hash(sdk),arts["binary_sha256"].as_str().unwrap());pin(sdk,&mut pins);
 let mut metadata=BTreeMap::new();for(name,argv)in[("perf",vec!["perf","version"]),("kernel",vec!["uname","-a"]),("cpu",vec!["lscpu","-J"])]{let o=Command::new(argv[0]).args(&argv[1..]).output().unwrap();assert!(o.status.success());metadata.insert(name.to_owned(),String::from_utf8(o.stdout).unwrap());}for name in["event","umask","cmask"]{metadata.insert(format!("cpu/format/{name}"),fs::read_to_string(format!("/sys/bus/event_source/devices/cpu/format/{name}")).unwrap());}save(r.join("host.json"),&json!(metadata));
 let mut definitions=Vec::new();for(name,code,umask,file)in[("de_no_dispatch_per_slot.no_ops_from_frontend","0x1a0","0x01","decode"),("de_no_dispatch_per_slot.backend_stalls","0x1a0","0x1e","decode"),("de_no_dispatch_per_slot.smt_contention","0x1a0","0x60","decode"),("de_src_op_disp.all","0xaa","0x07","decode"),("ex_ret_ops","0xc1","","execution"),("ic_cache_fill_l2","0x82","","inst-cache"),("ic_cache_fill_sys","0x83","","inst-cache")]{let table=read(r.join(format!("counter-sources/{file}.json")));let e=table.as_array().unwrap().iter().find(|e|e["EventName"]==name).unwrap();assert_eq!(e["EventCode"],code);if !umask.is_empty(){assert_eq!(e["UMask"],umask);}definitions.push(json!({"definition":e,"file":format!("counter-sources/{file}.json"),"url":format!("https://raw.githubusercontent.com/torvalds/linux/master/tools/perf/pmu-events/arch/x86/amdzen5/{file}.json")}));}
 save(r.join("event-definitions.json"),&json!({"definitions":definitions,"cycles":"perf generic cycles:u resolves to cpu/event=0x76/ on this host","instructions":"perf generic instructions:u resolves to0xc0","latency_condition":"frontend no-ops event with cmask8 counts cycles with at least8empty slots; Linux pipeline metric multiplies by8 and divides8*cycles","peak_dispatch_slots_per_user_cycle":8,"no_0x18e":true}));
 let old=read("/tmp/zopro-streamed-complex-sdk/perf-plan.json");let mut prior:BTreeSet<String>=serde_json::from_value(old["prior_proof_sha256"].clone()).unwrap();let before=prior.len();let inventory=read("/tmp/zopro-streamed-complex-sdk/proof-inventory.json");let mut exported=0;for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(p,&mut pins);if p.ends_with(".proof"){exported+=1;prior.insert(h.as_str().unwrap().into());}}assert_eq!(exported,237);save(r.join("prior-proof-sha256.json"),&json!(prior));save(r.join("prior-proof-audit.json"),&json!({"source":"/tmp/zopro-streamed-complex-sdk/proof-inventory.json","source_files_hashed":inventory.as_object().unwrap().len(),"prior_before":before,"source_exports":exported,"prior_for_this_experiment":prior.len()}));
 for path in["/tmp/zopro-grouping-module/production-source-manifest.json","/tmp/zopro-grouping-module/native/candidate/artifacts.json","/tmp/zopro-streamed-complex-sdk/proof-inventory.json","/tmp/zopro-streamed-complex-sdk/perf-plan.json","/tmp/zopro-gnark-verify/verify","/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock","/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask"]{pin(path,&mut pins);}
 let cases=vec![json!({"name":"primary32","shape":"1x2","workers":32,"rounds":401,"stem":"transfer_confidential_1_2","fixture":"transfer-1x2","affinity":null}),json!({"name":"primary16","shape":"1x2","workers":16,"rounds":201,"stem":"transfer_confidential_1_2","fixture":"transfer-1x2","affinity":"0-15"}),json!({"name":"merge54","shape":"merge-54x1","workers":32,"rounds":17,"stem":"merge_54_1","fixture":"merge-54x1","affinity":null})];
 let mut availability=vec![json!({"kind":"command","name":"work-link","argv":["rustc","--edition=2021","-O",r.join("availability-work.rs"),"-o",r.join("availability-work")],"timeout_seconds":120})];let mut all_steps=Vec::new();let mut order=Vec::new();let mut verify_steps=Vec::new();for(panel,events)in panels(){availability.push(json!({"kind":"command","name":format!("availability-{panel}"),"argv":["sudo","-n","perf","stat","--no-big-num","-x",";","-e",format!("{{{}}}",events.join(",")),"--","taskset","-c","2",r.join("availability-work"),"10000000"],"timeout_seconds":60}));}
 for block in 0..3{let mut indices=(0..9).map(|i|(i+block)%9).collect::<Vec<_>>();if block%2==1{indices.reverse();}for index in indices{let (panel,events)=&panels()[index%3];let c=&cases[index/3];let name=format!("b{block}-{}-{panel}",c["name"].as_str().unwrap());let dir=r.join("counter-data").join(&name);fs::create_dir_all(&dir).unwrap();let ctl=dir.join("ctl");let ack=dir.join("ack");assert!(Command::new("mkfifo").args(["-m","600"]).arg(&ctl).arg(&ack).status().unwrap().success());let stem=c["stem"].as_str().unwrap();let image=format!("/tmp/zopro-canonical-grain-adoption/images/{stem}.image");let key=format!("/tmp/zopro-keys/{stem}.zopro");let request=format!("/home/ubuntu/src/zk-tools/zopro/tools/zolana/fixtures/{}.json",c["fixture"].as_str().unwrap());for p in[&image,&key,&request]{pin(p,&mut pins);}
 let proofroot=r.join("proofs").join(&name);let proof=proofroot.join(stem);let csv=dir.join("counters.csv");let mut argv=vec!["sudo".to_owned(),"-n".into(),"perf".into(),"stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),format!("{{{}}}",events.join(",")),"-o".into(),csv.to_str().unwrap().into(),"--delay=-1".into(),format!("--control=fifo:{},{}",ctl.display(),ack.display()),"--".into(),"runuser".into(),"-u".into(),"ubuntu".into(),"--".into(),"env".into()];let mut env=base["environment"].as_object().unwrap().clone();env.insert("RAYON_NUM_THREADS".into(),json!(c["workers"].as_u64().unwrap().to_string()));env.insert("ZOPRO_BENCH_PERF_CTL".into(),json!(ctl));env.insert("ZOPRO_BENCH_PERF_ACK".into(),json!(ack));for(k,v)in env{argv.push(format!("{k}={}",v.as_str().unwrap()));}if let Some(affinity)=c["affinity"].as_str(){argv.extend(["taskset".into(),"-c".into(),affinity.into()]);}argv.extend([sdk.into(),image.clone(),request.clone(),c["rounds"].to_string(),proof.to_str().unwrap().into()]);all_steps.push(json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":600}));verify_steps.push(json!({"kind":"command","name":format!("gnark-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",proofroot,"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":600}));order.push(json!({"name":name,"block":block,"case":c,"panel":panel,"events":events,"csv":csv,"proof":proof,"image":image,"request":request}));}}
 all_steps.extend(verify_steps);assert_eq!(all_steps.len(),54);save(r.join("capture-order.json"),&json!(order));save(r.join("capture-template.json"),&json!({"version":1,"source_pins":r.join("capture-pins.json"),"environment":{},"steps":all_steps}));
 for name in["experiment.json","availability-work.rs","prepare.rs","host.json","event-definitions.json","prior-proof-sha256.json","prior-proof-audit.json","capture-order.json","capture-template.json","counter-sources/decode.json","counter-sources/execution.json","counter-sources/inst-cache.json","counter-sources/pipeline.json"]{pin(r.join(name),&mut pins);}save(r.join("input-pins.json"),&json!(pins));save(r.join("availability-plan.json"),&json!({"version":1,"source_pins":r.join("input-pins.json"),"environment":{},"steps":availability}));println!("Frozen{}pins4804priorproofs;3availabilitypanels then27warmcaptures54steps; exact acceptedSDK",pins.len());}
fn finalize(r:&Path){assert_eq!(read(r.join("availability/result.json"))["status"],"complete");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("input-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 let mut rows=Vec::new();for(panel,_)in panels(){let d=r.join("availability").join(format!("availability-{panel}"));receipt(&d);let s=fs::read_to_string(d.join("stderr.log")).unwrap();let records=s.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')).filter_map(|l|{let f=l.split(';').collect::<Vec<_>>();if f.len()<5{return None;}let count:f64=f[0].trim().parse().expect("unsupported or invalid event count");let running:f64=f[4].trim().parse().expect("invalid running percent");assert!(running>=99.);Some(json!({"event":f[2],"count":count,"running_percent":running}))}).collect::<Vec<_>>();assert_eq!(records.len(),4);assert!(records[0]["count"].as_f64().unwrap()>0.);rows.push(json!({"panel":panel,"records":records}));for name in["command.json","exit.json","stdout.log","stderr.log"]{pin(d.join(name),&mut pins);}}
 for name in["availability-plan.json","availability/result.json","availability-work"]{pin(r.join(name),&mut pins);}save(r.join("availability-check.json"),&json!({"status":"passed","panels":rows,"all_four_event_groups_supported":true,"minimum_running_percent":99,"no_sdk_requests_yet":true}));pin(r.join("availability-check.json"),&mut pins);save(r.join("capture-pins.json"),&json!(pins));save(r.join("capture-plan.json"),&read(r.join("capture-template.json")));println!("AvailabilityPASS3four-eventpanels; capture frozen{}pins",pins.len());}
